using System.Diagnostics;

namespace Viro.Agent.Repair;

/// <summary>
/// SAFE   - regenerated by Windows/apps automatically; may be cleaned by policy.
/// REVIEW - recoverable but the user may want it (recycle bin, previous Windows install); needs explicit administrator approval.
/// PERSONAL data (Documents, Desktop, Downloads, Pictures, Videos, user files) has NO category here at all: it is never
/// scanned and never deleted by any code path in this agent.
/// </summary>
public enum CleanClass { Safe, Review }

public sealed record CleanTarget(string Root, string Pattern = "*", bool Recursive = true, int MinAgeDays = 0, int MinAgeMinutes = 0);
public sealed record CleanCategory(string Id, string Title, string Description, CleanClass Class, Func<RepairEnv, IEnumerable<CleanTarget>> Targets, bool NeedsProcess = false);

/// <param name="RecentBytes">size of files that match the category but are too new to delete safely by default; reported so a run that frees little can say why</param>
public sealed record CategoryResult(string Id, string Title, string Class, long BytesFound, long FilesFound, long BytesFreed, long FilesRemoved, int Skipped, string? Note, long RecentBytes = 0, long RecentFiles = 0);

public static class Cleanup
{
    public static readonly string[] PersonalFoldersNeverTouched = ["Documents", "Desktop", "Downloads", "Pictures", "Videos", "Music", "OneDrive"];

    public static readonly IReadOnlyList<CleanCategory> Catalog =
    [
        new("windows-temp", "Windows temporary files", "Files in the Windows Temp folder older than 2 days.", CleanClass.Safe,
            e => [new(Path.Combine(e.WindowsDir, "Temp"), MinAgeDays: 2)]),
        new("recent-temp", "Recent temporary files", "Temp folders of Windows and every user, including files from the last two days. Anything in use, and anything changed in the last hour, is left alone.", CleanClass.Review,
            e => e.UserProfiles().Select(p => new CleanTarget(Path.Combine(p, "AppData", "Local", "Temp"), MinAgeMinutes: 60))
                .Concat([new CleanTarget(Path.Combine(e.WindowsDir, "Temp"), MinAgeMinutes: 60)])),
        new("user-temp", "User temporary files", "Temp folders of each user profile, files older than 2 days.", CleanClass.Safe,
            e => e.UserProfiles().Select(p => new CleanTarget(Path.Combine(p, "AppData", "Local", "Temp"), MinAgeDays: 2))),
        new("crash-dumps", "Crash dumps and error reports", "Memory dumps and Windows Error Reporting queues.", CleanClass.Safe,
            e => e.UserProfiles().Select(p => new CleanTarget(Path.Combine(p, "AppData", "Local", "CrashDumps")))
                .Concat([new(Path.Combine(e.WindowsDir, "Minidump")), new(Path.Combine(e.WindowsDir, "LiveKernelReports"), "*.dmp"),
                         new(Path.Combine(e.WindowsDir, "MEMORY.DMP"), "*", false),
                         new(Path.Combine(e.ProgramDataDir, "Microsoft", "Windows", "WER", "ReportArchive")), new(Path.Combine(e.ProgramDataDir, "Microsoft", "Windows", "WER", "ReportQueue"))])),
        new("update-leftovers", "Windows Update download cache", "Already-downloaded update packages Windows re-downloads if needed.", CleanClass.Safe,
            e => [new(Path.Combine(e.WindowsDir, "SoftwareDistribution", "Download")),
                  new(Path.Combine(e.WindowsDir, "ServiceProfiles", "NetworkService", "AppData", "Local", "Microsoft", "Windows", "DeliveryOptimization", "Cache"))]),
        new("browser-cache", "Browser caches", "Chrome, Edge and Firefox cache folders only (never cookies, history or passwords).", CleanClass.Safe,
            e => e.UserProfiles().SelectMany(p => new[]
            {
                "Google\\Chrome\\User Data\\*\\Cache", "Google\\Chrome\\User Data\\*\\Code Cache", "Google\\Chrome\\User Data\\*\\GPUCache",
                "Microsoft\\Edge\\User Data\\*\\Cache", "Microsoft\\Edge\\User Data\\*\\Code Cache", "Microsoft\\Edge\\User Data\\*\\GPUCache",
                "Mozilla\\Firefox\\Profiles\\*\\cache2",
            }.Select(rel => new CleanTarget(Path.Combine(p, "AppData", "Local", rel))))),
        new("thumbnail-cache", "Thumbnail cache", "Explorer thumbnail databases (rebuilt automatically).", CleanClass.Safe,
            e => e.UserProfiles().Select(p => new CleanTarget(Path.Combine(p, "AppData", "Local", "Microsoft", "Windows", "Explorer"), "thumbcache_*.db", false))),
        new("old-logs", "Old Windows logs", "CBS logs and cabinet archives older than 30 days.", CleanClass.Safe,
            e => [new(Path.Combine(e.WindowsDir, "Logs", "CBS"), "*.cab", false, 30), new(Path.Combine(e.WindowsDir, "Logs", "CBS"), "*.log", false, 30)]),

        new("recycle-bin", "Recycle Bin", "Files users deleted but may still want back.", CleanClass.Review,
            e => [new(Path.Combine(e.SystemDrive, "$Recycle.Bin"))]),
        new("windows-old", "Previous Windows installation", "Windows.old and upgrade leftovers (removes the ability to roll back the last upgrade).", CleanClass.Review,
            e => [new(Path.Combine(e.SystemDrive, "Windows.old")), new(Path.Combine(e.SystemDrive, "$WINDOWS.~BT")), new(Path.Combine(e.SystemDrive, "$WinREAgent"))], NeedsProcess: true),
    ];

    public static IEnumerable<string> SafeIds => Catalog.Where(c => c.Class == CleanClass.Safe).Select(c => c.Id);
    public static IEnumerable<string> ReviewIds => Catalog.Where(c => c.Class == CleanClass.Review).Select(c => c.Id);

    // ---------------------------------------------------------------------------------------------------
    static bool IsReparse(FileSystemInfo f) => (f.Attributes & FileAttributes.ReparsePoint) != 0;

    /// <summary>Expands a path containing '*' directory segments (e.g. "User Data\*\Cache") into existing directories.</summary>
    public static IEnumerable<string> ExpandRoot(string root)
    {
        var parts = root.Split(Path.DirectorySeparatorChar);
        var star = Array.FindIndex(parts, p => p.Contains('*') && !p.Contains('.'));
        if (star < 0) { yield return root; yield break; }
        var baseDir = string.Join(Path.DirectorySeparatorChar, parts[..star]);
        if (!Directory.Exists(baseDir)) yield break;
        IEnumerable<string> subs; try { subs = Directory.EnumerateDirectories(baseDir, parts[star]).ToList(); } catch { yield break; }
        foreach (var d in subs)
        {
            if (IsReparse(new DirectoryInfo(d))) continue;
            foreach (var r in ExpandRoot(Path.Combine([d, .. parts[(star + 1)..]]))) yield return r;
        }
    }

    /// <summary>Files under a target older than its minimum age. Never follows junctions/symlinks.</summary>
    public static IEnumerable<FileInfo> Enumerate(CleanTarget t, DateTime nowUtc, Stopwatch budget, TimeSpan limit, CancellationToken ct, Action<long>? tooNew = null)
    {
        var cutoff = nowUtc.AddDays(-t.MinAgeDays).AddMinutes(-t.MinAgeMinutes);
        foreach (var root in ExpandRoot(t.Root))
        {
            if (File.Exists(root)) { var fi = new FileInfo(root); if (!IsReparse(fi)) { if (fi.LastWriteTimeUtc <= cutoff) yield return fi; else if (tooNew is not null) { try { tooNew(fi.Length); } catch { } } } continue; }
            var top = new DirectoryInfo(root);
            if (!top.Exists || IsReparse(top)) continue;
            var stack = new Stack<DirectoryInfo>(); stack.Push(top);
            while (stack.Count > 0)
            {
                ct.ThrowIfCancellationRequested();
                if (budget.Elapsed > limit) yield break;
                var dir = stack.Pop();
                FileSystemInfo[] entries;
                try { entries = dir.GetFileSystemInfos(); } catch { continue; }
                foreach (var e in entries)
                {
                    if (IsReparse(e)) continue;
                    if (e is DirectoryInfo sub) { if (t.Recursive) stack.Push(sub); }
                    else if (e is FileInfo f && Matches(f.Name, t.Pattern)) { if (f.LastWriteTimeUtc <= cutoff) yield return f; else if (tooNew is not null) { try { tooNew(f.Length); } catch { } } }
                }
            }
        }
    }

    static bool Matches(string name, string pattern) => pattern == "*" || System.IO.Enumeration.FileSystemName.MatchesSimpleExpression(pattern, name, ignoreCase: true);

    public static List<CategoryResult> Preview(RepairEnv env, IEnumerable<string>? ids, Func<DateTime>? now = null, TimeSpan? perCategory = null, CancellationToken ct = default)
    {
        var res = new List<CategoryResult>();
        foreach (var c in Select(ids))
        {
            var sw = Stopwatch.StartNew(); long bytes = 0, files = 0, recentBytes = 0, recentFiles = 0; string? note = null;
            try
            {
                foreach (var t in c.Targets(env))
                    foreach (var f in Enumerate(t, (now ?? (() => DateTime.UtcNow))(), sw, perCategory ?? TimeSpan.FromSeconds(60), ct, n => { recentBytes += n; recentFiles++; })) { try { bytes += f.Length; files++; } catch { } }
                if (sw.Elapsed > (perCategory ?? TimeSpan.FromSeconds(60))) note = "size is a partial estimate (scan time limit reached)";
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception e) { note = "scan error: " + e.Message; }
            res.Add(new(c.Id, c.Title, c.Class.ToString().ToUpperInvariant(), bytes, files, 0, 0, 0, note, recentBytes, recentFiles));
        }
        return res;
    }

    /// <summary>Deletes eligible files. Locked/in-use files are skipped, never forced. Returns actual bytes freed.</summary>
    public static async Task<List<CategoryResult>> RunAsync(RepairEnv env, IProcessRunner proc, IEnumerable<string> ids, bool approveReview, Func<DateTime>? now = null, CancellationToken ct = default)
    {
        var chosen = Select(ids).ToList();
        foreach (var c in chosen) if (c.Class == CleanClass.Review && !approveReview) throw new InvalidOperationException($"category \"{c.Id}\" is REVIEW and requires explicit administrator approval");
        var res = new List<CategoryResult>();
        foreach (var c in chosen)
        {
            ct.ThrowIfCancellationRequested();
            var sw = Stopwatch.StartNew(); long found = 0, freed = 0, filesFound = 0, removed = 0, recentBytes = 0, recentFiles = 0; var skipped = 0; string? note = null;
            try
            {
                var touchedDirs = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var t in c.Targets(env))
                {
                    foreach (var f in Enumerate(t, (now ?? (() => DateTime.UtcNow))(), sw, TimeSpan.FromMinutes(10), ct, n => { recentBytes += n; recentFiles++; }))
                    {
                        long len; try { len = f.Length; } catch { skipped++; continue; }
                        found += len; filesFound++;
                        try { f.Attributes = FileAttributes.Normal; f.Delete(); freed += len; removed++; if (f.DirectoryName is { } d) touchedDirs.Add(d); }
                        catch { skipped++; } // in use, access denied, etc.: leave it
                    }
                    foreach (var root in ExpandRoot(t.Root).Where(Directory.Exists)) RemoveEmptyDirs(root, keepRoot: true);
                }
                if (c.NeedsProcess && c.Id == "windows-old") note = await RemoveWindowsOldAsync(env, proc, ct);
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception e) { note = "error: " + e.Message; }
            if (note is null && skipped > 0) note = $"{skipped} file(s) were in use or protected and were left alone";
            if (sw.Elapsed > TimeSpan.FromMinutes(10)) note = (note is null ? "" : note + "; ") + "stopped at the 10-minute limit; run it again to continue";
            res.Add(new(c.Id, c.Title, c.Class.ToString().ToUpperInvariant(), found, filesFound, freed, removed, skipped, note, recentBytes, recentFiles));
        }
        return res;
    }

    static IEnumerable<CleanCategory> Select(IEnumerable<string>? ids)
    {
        if (ids is null) return Catalog;
        var want = ids.ToHashSet(StringComparer.OrdinalIgnoreCase);
        var unknown = want.Except(Catalog.Select(c => c.Id), StringComparer.OrdinalIgnoreCase).ToList();
        if (unknown.Count > 0) throw new InvalidOperationException("unknown cleanup category: " + string.Join(", ", unknown));
        return Catalog.Where(c => want.Contains(c.Id));
    }

    static void RemoveEmptyDirs(string dir, bool keepRoot)
    {
        try
        {
            foreach (var sub in Directory.EnumerateDirectories(dir)) { if (!IsReparse(new DirectoryInfo(sub))) RemoveEmptyDirs(sub, false); }
            if (!keepRoot && !Directory.EnumerateFileSystemEntries(dir).Any()) Directory.Delete(dir);
        }
        catch { /* in use or protected: leave it */ }
    }

    /// <summary>Windows.old is owned by TrustedInstaller; the documented way to remove it is takeown + icacls + rd.</summary>
    static async Task<string?> RemoveWindowsOldAsync(RepairEnv env, IProcessRunner proc, CancellationToken ct)
    {
        var dir = Path.Combine(env.SystemDrive, "Windows.old");
        if (!Directory.Exists(dir)) return null;
        await proc.RunAsync("takeown.exe", $"/F \"{dir}\" /R /D Y", TimeSpan.FromMinutes(10), ct);
        await proc.RunAsync("icacls.exe", $"\"{dir}\" /grant Administrators:F /T /C /Q", TimeSpan.FromMinutes(10), ct);
        var r = await proc.RunAsync("cmd.exe", $"/c rd /s /q \"{dir}\"", TimeSpan.FromMinutes(15), ct);
        return Directory.Exists(dir) ? "Windows.old could not be fully removed (some files in use)" : null;
    }
}
